INSERT INTO feature VALUES('std-authority','modules','The ambient authority','packages','partial','uncommon','mainstream languages','`std.authority` names `Authority`, a capability holding every host operation a landed module of `std` reaches, which `main` takes as its parameter and `gandr run` hands it once; `console` opens the standard streams'' root capability from it by attenuation, a capability holding fewer operations. The authority is durable until the checker admits a consumable capability.','surface-lowering surface-dispatcher','library/std/src/authority.gandr corpus/model/effects/hello.gandr corpus/model/console/answer.gandr','corpus/ledger/features/std-authority.gandr','#3509');
